"""Outbound fetch for the Linkweave link-unfurl worker.

See ``README.md`` for the fetch contract. ``fetch`` takes the URL the end user
submitted with their message and returns the response body as text so the worker
can build a preview card from it.

``url`` is attacker-controlled: it is whatever a user typed into a message box.
Treating it as a plain ``requests.get`` target lets any user turn the worker into
a probe of the network the worker runs on -- instance metadata services, mesh
sidecars, admin panels -- and read the response back through the preview card.
A redirect from an otherwise trusted host reaches the same places.

So each target is checked before a socket is opened, and re-checked on every
redirect hop. Non-routable space (loopback, RFC-1918, link-local, and the rest
of what ``ipaddress`` reports as not global) is refused by default. Deployments
that legitimately unfurl links served from their own private network opt in
explicitly with ``LINKWEAVE_ALLOWED_CIDRS``; ``LINKWEAVE_ALLOW_PRIVATE_TARGETS``
lifts filtering altogether. See ``README.md``.
"""

from __future__ import annotations

import ipaddress
import os
import socket
from urllib.parse import urljoin, urlsplit

import requests

TIMEOUT_SECONDS = 5
MAX_REDIRECTS = 10
ALLOWED_SCHEMES = ("http", "https")

# Refused even when an operator allowlists the surrounding range: these are the
# cloud metadata endpoints, and only LINKWEAVE_ALLOW_PRIVATE_TARGETS lifts them.
METADATA_ADDRESSES = frozenset(
    {ipaddress.ip_address("169.254.169.254"), ipaddress.ip_address("fd00:ec2::254")}
)

_TRUTHY = {"1", "true", "yes", "on"}


class BlockedTargetError(requests.exceptions.RequestException):
    """Raised when ``url`` points somewhere the worker must not fetch."""


def _enabled(name: str) -> bool:
    return os.environ.get(name, "").strip().lower() in _TRUTHY


def _allowed_cidrs() -> tuple[ipaddress.IPv4Network | ipaddress.IPv6Network, ...]:
    networks = []
    for entry in os.environ.get("LINKWEAVE_ALLOWED_CIDRS", "").split(","):
        entry = entry.strip()
        if not entry:
            continue
        try:
            networks.append(ipaddress.ip_network(entry, strict=False))
        except ValueError as exc:
            raise ValueError(f"LINKWEAVE_ALLOWED_CIDRS: {entry!r} is not a valid CIDR") from exc
    return tuple(networks)


def _is_permitted(
    address: ipaddress.IPv4Address | ipaddress.IPv6Address,
    allowed: tuple[ipaddress.IPv4Network | ipaddress.IPv6Network, ...],
) -> bool:
    if address in METADATA_ADDRESSES:
        return False
    if address.is_global:
        return True
    return any(address.version == net.version and address in net for net in allowed)


def _resolved_addresses(host: str, service: str) -> list[ipaddress.IPv4Address | ipaddress.IPv6Address]:
    try:
        infos = socket.getaddrinfo(host, service, proto=socket.IPPROTO_TCP)
    except socket.gaierror as exc:
        raise requests.exceptions.ConnectionError(f"cannot resolve {host!r}: {exc}") from exc
    return [ipaddress.ip_address(info[4][0]) for info in infos]


def _check_target(url: str) -> None:
    """Refuse ``url`` unless every address it can reach is permitted."""
    if _enabled("LINKWEAVE_ALLOW_PRIVATE_TARGETS"):
        return

    parts = urlsplit(url)
    scheme = parts.scheme.lower()
    if scheme not in ALLOWED_SCHEMES:
        raise BlockedTargetError(f"refusing {url!r}: unsupported scheme {parts.scheme!r}")

    host = parts.hostname
    if not host:
        raise BlockedTargetError(f"refusing {url!r}: no host")

    try:
        port = parts.port
    except ValueError as exc:
        raise BlockedTargetError(f"refusing {url!r}: invalid port") from exc
    service = str(port) if port is not None else ("443" if scheme == "https" else "80")

    try:
        addresses = [ipaddress.ip_address(host)]
    except ValueError:
        addresses = _resolved_addresses(host, service)

    allowed = _allowed_cidrs()
    for address in addresses:
        if not _is_permitted(address, allowed):
            raise BlockedTargetError(
                f"refusing {url!r}: {host} resolves to {address}, which is not a "
                "publicly routable address (set LINKWEAVE_ALLOWED_CIDRS to permit it)"
            )


def fetch(url: str) -> str:
    """Fetch ``url`` (a user-supplied target) and return the response body text."""
    target = url
    with requests.Session() as session:
        for _ in range(MAX_REDIRECTS):
            _check_target(target)
            resp = session.get(target, timeout=TIMEOUT_SECONDS, allow_redirects=False)
            if not resp.is_redirect:
                resp.raise_for_status()
                return resp.text
            target = urljoin(target, resp.headers["Location"])

    raise requests.exceptions.TooManyRedirects(f"exceeded {MAX_REDIRECTS} redirects for {url!r}")
